fn parse_port(raw: &str) -> Result<u16, String> {
    let port: u16 = raw.parse().map_err(|e| format!("puerto inválido: {e}"))?;
    if port == 0 {
        return Err("el puerto no puede ser 0".into());
    }
    Ok(port)
}

TypeScript.ejemplo:
type ApiResult<T> =
  | { ok: true; data: T }
  | { ok: false; error: string };

function handle(res: ApiResult<number>): number {
  if (!res.ok) throw new Error(res.error);
  return res.data * 2; // narrowing automático: res.data es number
}
